import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Konto und Anmeldung","description":"Anmeldung, Profil, Hilfe und Löschen des Kontos.","frontmatter":{"title":"Konto und Anmeldung","description":"Anmeldung, Profil, Hilfe und Löschen des Kontos."},"headers":[],"relativePath":"erste-schritte/konto-und-anmeldung.md","filePath":"erste-schritte/konto-und-anmeldung.md","lastUpdated":1786170655000}'),a={name:"erste-schritte/konto-und-anmeldung.md"};function o(s,e,l,d,u,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="konto-und-anmeldung" tabindex="-1">Konto und Anmeldung <a class="header-anchor" href="#konto-und-anmeldung" aria-label="Permalink to &quot;Konto und Anmeldung&quot;">​</a></h1><h2 id="anmelden" tabindex="-1">Anmelden <a class="header-anchor" href="#anmelden" aria-label="Permalink to &quot;Anmelden&quot;">​</a></h2><p>Die Anmeldung erfolgt über eine eigene Anmeldeseite:</p><blockquote><p><strong>Willkommen!</strong><em>Geben Sie die Anmeldeinformationen ein.</em></p></blockquote><p>Sie geben <strong>Benutzername</strong> und <strong>Passwort</strong> ein und bestätigen mit <strong>Anmelden</strong>.</p><p>Bei falschen Angaben erscheint <em>Bitte überprüfen Sie Benutzername und Passwort</em>; fehlen sie ganz: <em>Benutzername ist ein Pflichtfeld</em> beziehungsweise <em>Passwort ist ein Pflichtfeld</em>.</p><div class="tip custom-block"><p class="custom-block-title">Kein Konto für Formulare nötig</p><p>Wer nur ein <a href="/docs/formulare/formular-erstellen">Formular</a> ausfüllt oder ein <a href="/docs/seiten/portal-veroeffentlichen">Portal</a> ansieht, braucht <strong>kein</strong> ApptiveGrid-Konto — es sei denn, der Zugriff wurde ausdrücklich beschränkt.</p><p>Ein Konto brauchen Sie erst, um selbst Grids, Formulare, Flows oder Seiten zu bauen.</p></div><h2 id="beim-start" tabindex="-1">Beim Start <a class="header-anchor" href="#beim-start" aria-label="Permalink to &quot;Beim Start&quot;">​</a></h2><p>Nach der ersten Anmeldung fragt ApptiveGrid:</p><blockquote><p><em>In welchem Bereich möchtest du ApptiveGrid einsetzen?</em></p></blockquote><p>Zur Auswahl stehen <strong>Privat</strong>, <strong>Arbeit</strong> und <strong>Sonstiges</strong>.</p><p>Danach begrüßt Sie die Space-Übersicht — je nach Tageszeit mit <em>Guten Morgen</em>, <em>Hallo</em>, <em>Willkommen</em> oder <em>Guten Abend</em>.</p><h2 id="angemeldetes-konto-prufen" tabindex="-1">Angemeldetes Konto prüfen <a class="header-anchor" href="#angemeldetes-konto-prufen" aria-label="Permalink to &quot;Angemeldetes Konto prüfen&quot;">​</a></h2><p>An geteilten Geräten kann es passieren, dass noch jemand anderes angemeldet ist. ApptiveGrid weist darauf hin:</p><blockquote><p><em>Sie sind als {E-Mail} angemeldet.</em><em>Bitte fahren Sie nur fort, wenn dies Ihr eigenes Konto ist.</em></p></blockquote><p>Mit <strong>Ja, ich bin {Name} - weiter</strong> bestätigen Sie, mit <strong>Anderes Konto verwenden</strong> wechseln Sie.</p><div class="tip custom-block"><p class="custom-block-title">Dieselbe Prüfung für Formulare und Seiten</p><p>Bei <a href="/docs/formulare/formular-erstellen">Formularen</a> und <a href="/docs/seiten/seitenlayout">Seiten</a> gibt es die Einstellung <em>Richtiges Konto bestätigen</em> beziehungsweise <em>Hinweis zur Konto-Bestätigung anzeigen</em>.</p><p>Für Anwendungen an Werkstatt-, Empfangs- oder Schulungsrechnern lohnt sich das — sonst werden Einträge unter fremdem Namen abgesendet.</p></div><h2 id="profil" tabindex="-1">Profil <a class="header-anchor" href="#profil" aria-label="Permalink to &quot;Profil&quot;">​</a></h2><p>Über <strong>Profil &amp; Einstellungen</strong> → <strong>Profil</strong>:</p><table tabindex="0"><thead><tr><th>Angabe</th><th></th></tr></thead><tbody><tr><td><strong>Profilbild</strong></td><td>Ihr Bild</td></tr><tr><td><strong>Vorname</strong>, <strong>Nachname</strong></td><td>Name, der anderen angezeigt wird</td></tr><tr><td><strong>E-Mail</strong></td><td>Ihre Adresse</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Für Profilbilder gilt eine Beschränkung</p><p><em>Wähle ein Bild mit dem Format jpg.</em> und <em>Die Datei ist zu groß. Wähle ein Bild kleiner als 1MB.</em></p></div><p>Ihr Name erscheint in der Spalte <strong>Erstellt von</strong> und im <a href="/docs/grids/versionsverlauf">Versionsverlauf</a> — für andere Personen im Space nachvollziehbar.</p><h2 id="konto-einstellungen-und-space-einstellungen" tabindex="-1">Konto-Einstellungen und Space-Einstellungen <a class="header-anchor" href="#konto-einstellungen-und-space-einstellungen" aria-label="Permalink to &quot;Konto-Einstellungen und Space-Einstellungen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Eine häufige Verwechslung</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Gilt für</th></tr></thead><tbody><tr><td><strong>Profil &amp; Einstellungen</strong></td><td>Sie persönlich — Profil, Abrechnung, API-Zugangsdaten</td></tr><tr><td><strong>Space Einstellungen</strong></td><td>Einen Space — Tarif, Sitzplätze, Webhooks, Links</td></tr></tbody></table><p>Der Tarif wird je <strong>Space</strong> gebucht, die Zahlungsdaten hängen aber am <strong>Konto</strong>.</p></div><p>→ <a href="/docs/spaces/einstellungen">Space-Einstellungen</a></p><h2 id="abrechnung" tabindex="-1">Abrechnung <a class="header-anchor" href="#abrechnung" aria-label="Permalink to &quot;Abrechnung&quot;">​</a></h2><p>Unter <strong>Abrechnung</strong>:</p><blockquote><p><em>Verwalte Abonnements, lade Rechnungen und bearbeite Zahlungs- oder Rechnungsdaten</em></p></blockquote><p>Die Schaltfläche <strong>Rechnungen und Abonnement</strong> führt zum Zahlungsanbieter.</p><h2 id="api-zugangsdaten" tabindex="-1">API-Zugangsdaten <a class="header-anchor" href="#api-zugangsdaten" aria-label="Permalink to &quot;API-Zugangsdaten&quot;">​</a></h2><p>Unter <strong>API Zugangsdaten</strong> erzeugen Sie Schlüssel für den Zugriff über die Programmierschnittstelle.</p><div class="danger custom-block"><p class="custom-block-title">Persönlich und weitreichend</p><blockquote><p><em>Ihre persönlichen API Anmeldeinformationen gewähren Zugriff auf alle Daten in Ihren Spaces. Geben Sie diese Anmeldeinformationen nur an Dienste und Anwendungen von Drittanbietern weiter, denen Sie vertrauen.</em></p></blockquote></div><p>→ <a href="/docs/integrationen/api-zugangsdaten">API-Zugangsdaten</a></p><h2 id="hilfe" tabindex="-1">Hilfe <a class="header-anchor" href="#hilfe" aria-label="Permalink to &quot;Hilfe&quot;">​</a></h2><p>Über <strong>Hilfe &amp; Support</strong>:</p><table tabindex="0"><thead><tr><th>Eintrag</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Hilfe-Center</strong></td><td>Dokumentation</td></tr><tr><td><strong>Chatte mit uns</strong></td><td>Direkter Kontakt zum Support</td></tr><tr><td><strong>Senden Sie uns Feedback</strong></td><td>Rückmeldung zum Produkt</td></tr><tr><td><strong>Was ist neu?</strong></td><td>Neuerungen</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Der Chat ist der schnellste Weg</p><p>Bei Fragen, die diese Dokumentation nicht beantwortet — etwa zur Einrichtung einer Integration oder zu Tarifdetails — führt der Chat direkt zum Support.</p></div><p>Erscheint ein Hinweis auf eine neue Programmversion, laden Sie die Seite neu.</p><h2 id="vorabfunktionen" tabindex="-1">Vorabfunktionen <a class="header-anchor" href="#vorabfunktionen" aria-label="Permalink to &quot;Vorabfunktionen&quot;">​</a></h2><p>Im Profil gibt es einen Schalter mit dem Text <em>Teste unsere neuesten Funktionen</em>.</p><div class="warning custom-block"><p class="custom-block-title">Nur zum Ausprobieren</p><p>Damit werden Funktionen sichtbar, die noch in Entwicklung sind. Sie können sich ändern oder wieder verschwinden.</p><p>Verlassen Sie sich in Anleitungen für Ihr Team nicht darauf, und lassen Sie den Schalter im produktiven Einsatz aus.</p></div><h2 id="konto-loschen" tabindex="-1">Konto löschen <a class="header-anchor" href="#konto-loschen" aria-label="Permalink to &quot;Konto löschen&quot;">​</a></h2><p>Unter <strong>Profil</strong> → <strong>Account löschen</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Endgültig</p><blockquote><p><em>Ihr Account und alle Daten werden unwiderruflich gelöscht. Geben Sie DELETE in das Textfeld ein um fortzufahren.</em></p></blockquote><p>Sie müssen zur Bestätigung <code>DELETE</code> eintippen. Es gibt keine Wiederherstellung.</p><p><strong>Vorher prüfen:</strong> Sind Sie Eigentümer von Spaces, die andere weiterhin brauchen? Übertragen Sie diese vorher oder sichern Sie die Daten über einen <a href="/docs/grids/csv-export">CSV-Export</a>.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/erste-schritte/was-ist-apptivegrid">Was ist ApptiveGrid</a></li><li><a href="/docs/erste-schritte/oberflaeche">Die Oberfläche im Überblick</a></li><li><a href="/docs/zusammenarbeit/rollen">Rollen</a></li></ul>',46)])])}const m=n(a,[["render",o]]);export{g as __pageData,m as default};
